import { ObjectSerializer } from './index.js';
/**
* Contains mappings from target to a list of selected scopes
*/
export class PipelineSelectedScopes {
    'scopes';
    static discriminator = undefined;
    static attributeTypeMap = [
        {
            "name": "scopes",
            "baseName": "scopes",
            // false
            // Array&lt;UUID&gt;
            // Array&lt;UUID&gt;
            "type": "Array<UUID>",
            "format": "uuid"
        }
    ];
    static getAttributeTypeMap() {
        return PipelineSelectedScopes.attributeTypeMap;
    }
    static newInstance(obj) {
        return ObjectSerializer.deserialize(obj, 'PipelineSelectedScopes');
    }
    constructor(scopes) {
        this.scopes = scopes;
    }
}
