import { ObjectSerializer } from './index.js';
/**
* a simplified custom field model to pull into other models
*/
export class CustomFieldBase {
    /**
    * Unique identifier
    */
    'id';
    /**
    * The activity name
    */
    'name';
    /**
    * The activity code
    */
    'code';
    /**
    * The type of this field.
    */
    'type';
    /**
    * provided when the string type is an enumeration
    */
    'enumeration';
    'example';
    static discriminator = undefined;
    static attributeTypeMap = [
        {
            "name": "id",
            "baseName": "id",
            // false
            // UUID
            // UUID
            "type": "UUID",
            "format": "uuid"
        },
        {
            "name": "name",
            "baseName": "name",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        },
        {
            "name": "code",
            "baseName": "code",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        },
        {
            "name": "type",
            "baseName": "type",
            // false
            // any
            // any
            "type": "any",
            "format": ""
        },
        {
            "name": "enumeration",
            "baseName": "enumeration",
            // false
            // Array&lt;CustomFieldEnum&gt;
            // Array&lt;CustomFieldEnum&gt;
            "type": "Array<CustomFieldEnum>",
            "format": ""
        },
        {
            "name": "example",
            "baseName": "example",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        }
    ];
    static getAttributeTypeMap() {
        return CustomFieldBase.attributeTypeMap;
    }
    static newInstance(obj) {
        return ObjectSerializer.deserialize(obj, 'CustomFieldBase');
    }
    constructor(id, name, code, type, enumeration, example) {
        this.id = id;
        this.name = name;
        this.code = code;
        this.type = type;
        this.enumeration = enumeration;
        this.example = example;
    }
}
