import { ObjectSerializer } from './index.js';
/**
* A permission object that applies to a resource type. Some permissions are reserved for resources and may not include a resource type.
*/
export class Permission {
    /**
    * The name of the permission
    */
    'name';
    /**
    * the integer value of the permission
    */
    'value';
    /**
    * A description for this permission
    */
    'description';
    /**
    * the resource type this permission applies to
    */
    'resourceType';
    static discriminator = undefined;
    static attributeTypeMap = [
        {
            "name": "name",
            "baseName": "name",
            // false
            // Nmtoken
            // Nmtoken
            "type": "Nmtoken",
            "format": "nmtoken"
        },
        {
            "name": "value",
            "baseName": "value",
            // false
            // number
            // number
            "type": "number",
            "format": "int64"
        },
        {
            "name": "description",
            "baseName": "description",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        },
        {
            "name": "resourceType",
            "baseName": "resourceType",
            // false
            // Nmtoken
            // Nmtoken
            "type": "Nmtoken",
            "format": "nmtoken"
        }
    ];
    static getAttributeTypeMap() {
        return Permission.attributeTypeMap;
    }
    static newInstance(obj) {
        return ObjectSerializer.deserialize(obj, 'Permission');
    }
    constructor(name, value, description, resourceType) {
        this.name = name;
        this.value = value;
        this.description = description;
        this.resourceType = resourceType;
    }
}
