import { ObjectSerializer } from './index.js';
/**
* Schema for an object graph
*/
export class ObjectGraph {
    'classes';
    'nodes';
    'links';
    static discriminator = undefined;
    static attributeTypeMap = [
        {
            "name": "classes",
            "baseName": "classes",
            // false
            // Array&lt;ObjectGraphClass&gt;
            // Array&lt;ObjectGraphClass&gt;
            "type": "Array<ObjectGraphClass>",
            "format": ""
        },
        {
            "name": "nodes",
            "baseName": "nodes",
            // false
            // Array&lt;ObjectGraphNode&gt;
            // Array&lt;ObjectGraphNode&gt;
            "type": "Array<ObjectGraphNode>",
            "format": ""
        },
        {
            "name": "links",
            "baseName": "links",
            // false
            // Array&lt;ObjectGraphLink&gt;
            // Array&lt;ObjectGraphLink&gt;
            "type": "Array<ObjectGraphLink>",
            "format": ""
        }
    ];
    static getAttributeTypeMap() {
        return ObjectGraph.attributeTypeMap;
    }
    static newInstance(obj) {
        return ObjectSerializer.deserialize(obj, 'ObjectGraph');
    }
    constructor(classes, nodes, links) {
        this.classes = classes;
        this.nodes = nodes;
        this.links = links;
    }
}
