import { ObjectSerializer } from './index.js';
/**
* A condition that may be evaluated when requesting access to a resource Conditions may be of one of three types:































































































































































































































































































































































  * json: Evaluates json payload properties based on a path and operator
  * tag: Matches if the resource is tagged by the given tagId
  * function: matches if the given function evaluates to true
*/
export class ResourceSelectorCondition {
    /**
    * The id of the condition
    */
    'id';
    /**
    * The name of the condition
    */
    'name';
    /**
    * The id of the selector this condition applies to
    */
    'resourceSelectorId';
    'type';
    static discriminator = "type";
    static attributeTypeMap = [
        {
            "name": "id",
            "baseName": "id",
            // false
            // UUID
            // UUID
            "type": "UUID",
            "format": "uuid"
        },
        {
            "name": "name",
            "baseName": "name",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        },
        {
            "name": "resourceSelectorId",
            "baseName": "resourceSelectorId",
            // false
            // UUID
            // UUID
            "type": "UUID",
            "format": "uuid"
        },
        {
            "name": "type",
            "baseName": "type",
            // false
            // ResourceSelectorConditionType
            // ResourceSelectorConditionTypeDef
            "type": "ResourceSelectorConditionType",
            "format": ""
        }
    ];
    static getAttributeTypeMap() {
        return ResourceSelectorCondition.attributeTypeMap;
    }
    static newInstance(obj) {
        return ObjectSerializer.deserialize(obj, 'ResourceSelectorCondition');
    }
    constructor(id, name, resourceSelectorId, type) {
        this.id = id;
        this.name = name;
        this.resourceSelectorId = resourceSelectorId;
        this.type = type;
    }
}
