import { ObjectSerializer } from './index.js';
/**
* Model containing network interface information.
*/
export class NetworkInterface {
    /**
    * Network interface name
    */
    'name';
    /**
    * The hardware address for the given interface
    */
    'mac';
    /**
    * Indicator of whether or not this interface is currently up
    */
    'up';
    /**
    * All the network addresses assigned to this interface
    */
    'addresses';
    static discriminator = undefined;
    static attributeTypeMap = [
        {
            "name": "name",
            "baseName": "name",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        },
        {
            "name": "mac",
            "baseName": "mac",
            // false
            // MacAddress
            // MacAddress
            "type": "MacAddress",
            "format": "macaddr"
        },
        {
            "name": "up",
            "baseName": "up",
            // false
            // boolean
            // boolean
            "type": "boolean",
            "format": ""
        },
        {
            "name": "addresses",
            "baseName": "addresses",
            // false
            // Array&lt;NetworkAddress&gt;
            // Array&lt;NetworkAddress&gt;
            "type": "Array<NetworkAddress>",
            "format": ""
        }
    ];
    static getAttributeTypeMap() {
        return NetworkInterface.attributeTypeMap;
    }
    static newInstance(obj) {
        return ObjectSerializer.deserialize(obj, 'NetworkInterface');
    }
    constructor(name, mac, up, addresses) {
        this.name = name;
        this.mac = mac;
        this.up = up;
        this.addresses = addresses;
    }
}
