import { ObjectSerializer } from './index.js';
/**
* Simple object with id and name
*/
export class IdNameObject {
    'id';
    'name';
    static discriminator = undefined;
    static attributeTypeMap = [
        {
            "name": "id",
            "baseName": "id",
            // false
            // UUID
            // UUID
            "type": "UUID",
            "format": "uuid"
        },
        {
            "name": "name",
            "baseName": "name",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        }
    ];
    static getAttributeTypeMap() {
        return IdNameObject.attributeTypeMap;
    }
    static newInstance(obj) {
        return ObjectSerializer.deserialize(obj, 'IdNameObject');
    }
    constructor(id, name) {
        this.id = id;
        this.name = name;
    }
}
