import { ObjectSerializer } from './index.js';
/**
* Status object describing color and description
*/
export class StatusObject {
    'color';
    'description';
    static discriminator = undefined;
    static attributeTypeMap = [
        {
            "name": "color",
            "baseName": "color",
            // false
            // ColorStatusEnum
            // ColorStatusEnumDef
            "type": "ColorStatusEnum",
            "format": ""
        },
        {
            "name": "description",
            "baseName": "description",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        }
    ];
    static getAttributeTypeMap() {
        return StatusObject.attributeTypeMap;
    }
    static newInstance(obj) {
        return ObjectSerializer.deserialize(obj, 'StatusObject');
    }
    constructor(color, description) {
        this.color = color;
        this.description = description;
    }
}
