import { ObjectSerializer } from './index.js';
/**
* Types for tags
*/
export class TagType {
    /**
    * Name of this type
    */
    'name';
    /**
    * A longer description of the type
    */
    'description';
    /**
    * A hint for UIs displaying tags of this type.
    */
    'color';
    static discriminator = undefined;
    static attributeTypeMap = [
        {
            "name": "name",
            "baseName": "name",
            // false
            // Nmtoken
            // Nmtoken
            "type": "Nmtoken",
            "format": "nmtoken"
        },
        {
            "name": "description",
            "baseName": "description",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        },
        {
            "name": "color",
            "baseName": "color",
            // false
            // string
            // string
            "type": "string",
            "format": ""
        }
    ];
    static getAttributeTypeMap() {
        return TagType.attributeTypeMap;
    }
    static newInstance(obj) {
        return ObjectSerializer.deserialize(obj, 'TagType');
    }
    constructor(name, description, color) {
        this.name = name;
        this.description = description;
        this.color = color;
    }
}
